    Triple("preset:\"Hard words\" notetype:\"My cards\"", """SELECT c.id FROM app.card c JOIN app.note n ON n.id = c.note_id WHERE c.deleted_at IS NULL AND c.merged_into_id IS NULL AND n.deleted_at IS NULL AND (EXISTS (SELECT 1 FROM app.fsrs_params p WHERE p.id = c.preset_id AND translate(p.name, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz') LIKE ? ESCAPE '\') AND EXISTS (SELECT 1 FROM app.note_type nt WHERE nt.id = n.note_type_id AND translate(nt.name, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz') LIKE ? ESCAPE '\')) ## hard words | my cards""", """SELECT c.id FROM card c JOIN note n ON n.id = c.note_id WHERE c.deleted_at IS NULL AND c.merged_into_id IS NULL AND n.deleted_at IS NULL AND (EXISTS (SELECT 1 FROM fsrs_params p WHERE p.id = c.preset_id AND lower(p.name) LIKE ? ESCAPE '\') AND EXISTS (SELECT 1 FROM note_type nt WHERE nt.id = n.note_type_id AND lower(nt.name) LIKE ? ESCAPE '\')) ## hard words | my cards"""),
    Triple("kanji:績 or kanji:責", """SELECT c.id FROM app.card c JOIN app.note n ON n.id = c.note_id WHERE c.deleted_at IS NULL AND c.merged_into_id IS NULL AND n.deleted_at IS NULL AND (((n.kanji_literal IS NOT NULL AND n.kanji_literal = ?) OR (n.type = 'vocab' AND strpos(coalesce(n.fields ->> 'expression', ''), ?) > 0)) OR ((n.kanji_literal IS NOT NULL AND n.kanji_literal = ?) OR (n.type = 'vocab' AND strpos(coalesce(n.fields ->> 'expression', ''), ?) > 0))) ## 績 | 績 | 責 | 責""", """SELECT c.id, n.id, n.type, n.tags, n.fields, n.mnemonic, n.source_sentence, ((n.kanji_literal IS NOT NULL AND n.kanji_literal = ?)) AS p0, ((n.type = 'vocab' AND instr(n.fields, ?) > 0)) AS p1, ((n.kanji_literal IS NOT NULL AND n.kanji_literal = ?)) AS p2, ((n.type = 'vocab' AND instr(n.fields, ?) > 0)) AS p3, (((n.kanji_literal IS NOT NULL AND n.kanji_literal = ?) OR (n.type = 'vocab' AND instr(n.fields, ?) > 0))) AS p4, (((n.kanji_literal IS NOT NULL AND n.kanji_literal = ?) OR (n.type = 'vocab' AND instr(n.fields, ?) > 0))) AS p5 FROM card c JOIN note n ON n.id = c.note_id WHERE c.deleted_at IS NULL AND c.merged_into_id IS NULL AND n.deleted_at IS NULL AND (((n.kanji_literal IS NOT NULL AND n.kanji_literal = ?) OR (n.type = 'vocab' AND instr(n.fields, ?) > 0)) OR ((n.kanji_literal IS NOT NULL AND n.kanji_literal = ?) OR (n.type = 'vocab' AND instr(n.fields, ?) > 0))) ## 績 | 績 | 責 | 責 | 績 | 績 | 責 | 責 | 績 | 績 | 責 | 責"""),
    Triple("kanji:𠮟", """SELECT c.id FROM app.card c JOIN app.note n ON n.id = c.note_id WHERE c.deleted_at IS NULL AND c.merged_into_id IS NULL AND n.deleted_at IS NULL AND ((n.kanji_literal IS NOT NULL AND n.kanji_literal = ?) OR (n.type = 'vocab' AND strpos(coalesce(n.fields ->> 'expression', ''), ?) > 0)) ## 𠮟 | 𠮟""", """SELECT c.id, n.id, n.type, n.tags, n.fields, n.mnemonic, n.source_sentence, ((n.kanji_literal IS NOT NULL AND n.kanji_literal = ?)) AS p0, ((n.type = 'vocab' AND instr(n.fields, ?) > 0)) AS p1 FROM card c JOIN note n ON n.id = c.note_id WHERE c.deleted_at IS NULL AND c.merged_into_id IS NULL AND n.deleted_at IS NULL AND ((n.kanji_literal IS NOT NULL AND n.kanji_literal = ?) OR (n.type = 'vocab' AND instr(n.fields, ?) > 0)) ## 𠮟 | 𠮟 | 𠮟 | 𠮟"""),
