    Triple("stability>10.50 due>=-0 difficulty<0.0000001", """SELECT c.id FROM app.card c JOIN app.note n ON n.id = c.note_id WHERE c.deleted_at IS NULL AND c.merged_into_id IS NULL AND n.deleted_at IS NULL AND ((c.stability IS NOT NULL AND c.stability > ?) AND (c.due_at IS NOT NULL AND c.due_at >= to_timestamp(CAST(? AS double precision) / 1000.0)) AND (c.difficulty IS NOT NULL AND c.difficulty < ?)) ## 10.5 | 1700000000000 | 1e-7""", """SELECT c.id FROM card c JOIN note n ON n.id = c.note_id WHERE c.deleted_at IS NULL AND c.merged_into_id IS NULL AND n.deleted_at IS NULL AND ((c.stability IS NOT NULL AND c.stability > ?) AND (c.due_at IS NOT NULL AND c.due_at >= ?) AND (c.difficulty IS NOT NULL AND c.difficulty < ?)) ## 10.5 | 1700000000000 | 1e-7"""),
